window.LISTENING_DATA = [{"id":"2021-06-1","title":"2021年6月 第1套","audio":"listening/2021-06-1.ogg","duration":1382.84,"sentences":[{"s":1.61,"e":8.09,"en":"College English Test Band 4, Part 2, Listening Comprehension.","zh":"大学英语四级考试第二部分听力理解。"},{"s":8.09,"e":11.41,"en":"Section A, Directions.","zh":"A部分，方向。"},{"s":11.41,"e":15.45,"en":"In this section you'll hear three news reports.","zh":"在本部分中您将听到三条新闻报道。"},{"s":15.45,"e":20.57,"en":"At the end of each news report you'll hear two or three questions.","zh":"在每篇新闻报道结束时，你都会听到两三个问题。"},{"s":20.57,"e":25.35,"en":"Both the news report and the questions will be spoken only once.","zh":"新闻报道和问题都将只说一次。"},{"s":25.35,"e":34.35,"en":"After you hear a question you must choose the best answer from the four choices marked A, B, C and D.","zh":"听到问题后你必须选择标记的四个选项中的最佳答案A、B、C和D。"},{"s":34.35,"e":41.87,"en":"Then mark the corresponding letter on answer sheet 1 with a single line through the centre.","zh":"然后在答题纸上标记相应的字母1一条线穿过中心。"},{"s":41.87,"e":44.15,"en":"News Report 1.","zh":"新闻报道1."},{"s":44.15,"e":55.29,"en":"And finally, in tonight's news, a nine-year-old boy named Joe, told not to draw in class, lands a job decorating a restaurant with his drawings.","zh":"最后，今晚的新闻是，一名九岁的名叫乔的男孩被告知不要画画在课堂上找到了一份装饰餐厅的工作和他的绘画作品"},{"s":55.29,"e":67.71,"en":"Rather than shutting down the habit of drawing in his school's workbook, Joe's parents decided to encourage his creativity by sending their son to an after-school art class.","zh":"而不是放弃画画的习惯在学校的练习册里，乔的父母决定鼓励他的创造力，让他们的儿子课外艺术班"},{"s":67.71,"e":76.07,"en":"His teacher recognized Joe's talent and posted all his work online, which led to something pretty wonderful.","zh":"他的老师认识到了乔的才华，并公布了所有他在网上的工作，这导致了一件相当精彩的。"},{"s":76.07,"e":86.43,"en":"A restaurant named Number 4 in Newcastle contacted Joe's teacher to ask if the nine-year-old could come and decorate its dining room with his drawings.","zh":"纽卡斯尔一家名为Number4的餐厅联系了乔的老师问九年制-老可以来装饰它的餐厅和他的绘画作品"},{"s":86.43,"e":94.49,"en":"Every day after school, Joe's dad drives him to the restaurant so he can put his ideas straight on the wall.","zh":"每天放学后，乔的爸爸都会开车送他去餐厅，这样他就可以把想法直接写在墙上。"},{"s":94.49,"e":98.81,"en":"Once he's all done, the work will remain there permanently.","zh":"一旦他完成了所有工作，工作将继续永久地存在在那里。"},{"s":98.81,"e":102.87,"en":"Joe's dad said, Joe is a really talented little boy.","zh":"乔的爸爸说，乔真的很有天赋小男孩。"},{"s":102.87,"e":111.01,"en":"He's excellent at school, he's great at football, but drawing is definitely what he is most passionate about.","zh":"他在学校表现优异，踢足球也很棒，但绘画绝对是他最擅长的热衷于。"},{"s":111.01,"e":116.27,"en":"Questions 1 and 2 are based on the news report you have just heard.","zh":"问题1和问题2基于您刚刚听到的新闻报道。"},{"s":116.27,"e":118.05,"en":"Question 1.","zh":"问题1."},{"s":118.05,"e":135.1,"en":"What did Joe's parents decide to do?","zh":"乔的父母决定做什么？"},{"s":135.1,"e":136.58,"en":"Question 2.","zh":"问题2."},{"s":136.58,"e":154.22,"en":"What did the restaurant Number 4 do?","zh":"4号餐厅是做什么的？"},{"s":154.22,"e":156.36,"en":"News Report 2.","zh":"新闻报道2."},{"s":156.36,"e":167.78,"en":"Kirsteen Marshall, a 34-year-old mum of one, posted a tearful video on social media Wednesday, begging for the safe return of her beloved pet dog.","zh":"34岁的KirsteenMarshall是一名一人在社交媒体上发布了一段令人泪流满面的视频星期三，祈求她平安归来心爱的宠物狗。"},{"s":167.78,"e":177.96,"en":"After combing through the security video outside a Gaubles shop, Kirsteen has now posted an image of a man suspected of stealing the dog.","zh":"在仔细查看了Gaubles商店，Kirsteen现已发布图片一名涉嫌偷狗的男子。"},{"s":177.96,"e":182.74,"en":"The image appears to show a man carrying the dog in his arms.","zh":"该图片显示一名男子携带他怀里的狗。"},{"s":182.74,"e":192.72,"en":"Kirsteen also believes the video obtained from the shop shows the dog being stolen by a man before driving off in a car which had been waiting nearby.","zh":"Kirsteen还认为，从商店显示狗被偷了男子开车离开前一直在附近等候。"},{"s":192.72,"e":203.28,"en":"The family is now offering a £5,000 reward for the safe return of the dog after launching a social media campaign to find the thief.","zh":"该家庭现在提供5,000英镑奖励狗安全归来在发起社交媒体活动寻找小偷。"},{"s":203.28,"e":209.22,"en":"The dog is six and a half years old and was last seen wearing a red collar.","zh":"这只狗六岁半最后一次露面时，身穿红色衣领。"},{"s":209.22,"e":217.2,"en":"Kirsteen said, we will pay that to anyone who brings him home as long as they are not responsible for his disappearance.","zh":"Kirsteen说，我们会向任何人支付这笔费用谁带他回家，只要他们对他的失踪不负任何责任。"},{"s":217.2,"e":220.82,"en":"Police are investigating the incident.","zh":"警方正在调查此事。"},{"s":220.82,"e":226.06,"en":"Questions 3 and 4 are based on the news report you have just heard.","zh":"问题3和问题4基于您刚刚听到的新闻报道。"},{"s":226.06,"e":227.58,"en":"Question 3.","zh":"问题3."},{"s":227.58,"e":245.12,"en":"What is Kirsteen Marshall trying to do?","zh":"柯尔斯汀·马歇尔KirsteenMarshall想做什么？"},{"s":245.12,"e":246.52,"en":"Question 4.","zh":"问题4."},{"s":246.52,"e":265.66,"en":"What does the news report say about Kirsteen Marshall's family?","zh":"新闻报道对Kirsteen有何评价马歇尔的家人？"},{"s":265.66,"e":267.74,"en":"News Report 3.","zh":"新闻报道3."},{"s":267.74,"e":278.48,"en":"London's Eggs and Bread Cafe offers boiled eggs, toast, jam, and bacon, as well as tea, coffee, and orange juice.","zh":"伦敦的EggsandBreadCafe提供煮鸡蛋，烤面包、果酱、培根，还有茶，咖啡和橙汁。"},{"s":278.48,"e":283.42,"en":"But at the end of the meal, customers don't have to worry about the bill.","zh":"但用餐结束时，顾客不用担心账单。"},{"s":283.42,"e":290.54,"en":"Hungry customers can pay whatever amount they can afford to eat at the cafe or nothing at all.","zh":"饥饿的顾客可以支付任意金额要么去咖啡馆吃饭，要么什么都不吃一点儿也不。"},{"s":290.54,"e":297.0,"en":"Owner Guy Wilson says his cafe aims to build community rather than profits.","zh":"老板盖伊·威尔逊GuyWilson表示，他的咖啡馆旨在建立社区而不是利润。"},{"s":297.0,"e":307.62,"en":"He wants to provide a bridge for people to connect in an area that has been divided by class and wealth by providing affordable breakfasts.","zh":"他想为人们搭建一座桥梁连接在已经通过提供负担得起的早餐。"},{"s":307.62,"e":316.18,"en":"The cafe is open in the mornings every day of the year and has two members of staff or supervisors on shift every day.","zh":"咖啡馆每天早上开放一年中的某一天，有两个成员每天轮班的员工或主管。"},{"s":316.18,"e":323.34,"en":"The cafe doesn't use volunteers but pays its staff to ensure consistency in its service.","zh":"这家咖啡馆不使用志愿者，而是支付工作人员以确保服务的一致性。"},{"s":323.34,"e":328.18,"en":"It doesn't take donations and doesn't want to be seen as a charity.","zh":"它不接受捐赠，也不想被视为一种慈善事业。"},{"s":328.18,"e":343.2,"en":"Mr. Wilson says when people start to know other people around them, they realize they're not that different, and whatever their financial background or their educational background, most people will have something in common with each other.","zh":"威尔逊先生说，当人们开始知道他们周围的其他人，他们意识到他们不是不同，无论他们的财务背景或他们的教育背景，大多数人都会有一些彼此有共同之处。"},{"s":343.2,"e":349.56,"en":"He says it's important that his cafe can offer his customers security and permanence.","zh":"他说，重要的是他的咖啡馆能够为客户提供安全性和永久性。"},{"s":349.56,"e":354.58,"en":"Questions 5 to 7 are based on the news report you have just heard.","zh":"问题5至7基于您刚刚听到的新闻报道。"},{"s":354.58,"e":355.86,"en":"Question 5.","zh":"问题5."},{"s":355.86,"e":374.06,"en":"What does Guy Wilson say his cafe aims to do?","zh":"盖伊·威尔逊说他的咖啡馆的目的是什么做什么？"},{"s":374.06,"e":375.44,"en":"Question 6.","zh":"问题6."},{"s":375.44,"e":394.26,"en":"What does the news report say about Eggs and Bread Cafe?","zh":"新闻报道对鸡蛋有何评价还有面包咖啡馆？"},{"s":394.26,"e":395.86,"en":"Question 7.","zh":"问题7."},{"s":395.86,"e":415.22,"en":"What happens when people start to know each other according to Guy Wilson?","zh":"当人们开始了解彼此时会发生什么盖伊·威尔逊GuyWilson认为其他的呢？"},{"s":415.22,"e":416.44,"en":"Section B.","zh":"B部分。"},{"s":416.44,"e":417.98,"en":"Directions.","zh":"方向。"},{"s":417.98,"e":421.6,"en":"In this section, you will hear two long conversations.","zh":"在本节中，你将听到两个长对话。"},{"s":421.6,"e":425.94,"en":"At the end of each conversation, you will hear four questions.","zh":"每次对话结束时，你将听四个问题。"},{"s":425.94,"e":430.8,"en":"Both the conversation and the questions will be spoken only once.","zh":"对话和问题都将只讲过一次。"},{"s":430.8,"e":439.46,"en":"After you hear a question, you must choose the best answer from the four choices marked A, B, C, and D.","zh":"听完问题后你必须选择标记的四个选项中的最佳答案A、B、C和D。"},{"s":439.46,"e":446.1,"en":"Then mark the corresponding letter on answer sheet one with a single line through the center.","zh":"然后在答题纸上标记相应的字母一条线穿过中心。"},{"s":446.1,"e":448.46,"en":"Conversation 1.","zh":"对话1。"},{"s":448.46,"e":452.28,"en":"So what time do you think we should have the party on Saturday?","zh":"那么你认为我们应该什么时候星期六有聚会吗？"},{"s":452.28,"e":460.14,"en":"How about inviting people to come at 6 p.m.? Then we'll have the afternoon to prepare food and drink and stuff like that.","zh":"邀请人们6点来怎么样下午？然后我们下午就可以准备食物、饮料之类的东西。"},{"s":460.14,"e":463.7,"en":"Yes, I was thinking that around 6 would be good too.","zh":"是的，我想6点左右也會很好。"},{"s":463.7,"e":465.82,"en":"What food should we provide?","zh":"我们应该提供什么食物？"},{"s":465.82,"e":469.64,"en":"Well, I had thought about baking a cake and some biscuits.","zh":"嗯，我曾经想过烤一个蛋糕还有一些饼干。"},{"s":469.64,"e":481.7,"en":"And now, I think we should prepare some sandwiches and snacks and some other kinds of food so that people can just help themselves rather than getting everyone to sit down at the table to eat a meal.","zh":"现在我想我们应该准备一些三明治、小吃和其他一些食物，这样人们就可以自助而不是让每个人都坐下来餐桌上吃饭。"},{"s":481.7,"e":484.1,"en":"I think that's a bit too formal.","zh":"我认为这有点太正式了。"},{"s":484.1,"e":489.74,"en":"It's better to let people walk around and talk to each other or sit where they like.","zh":"最好让人们四处走动互相交谈或坐在喜欢。"},{"s":489.74,"e":491.84,"en":"Yes, that sounds good.","zh":"是的，听起来不错。"},{"s":491.84,"e":494.98,"en":"I'll go to the supermarket to get some drinks.","zh":"我要去超市买一些饮料。"},{"s":494.98,"e":501.3,"en":"I think I might try that big new supermarket on the other side of town and see what they have.","zh":"我想我可能会尝试一下那个新东西城镇另一边的超市和看看他们有什么。"},{"s":501.3,"e":503.58,"en":"I've not been there before.","zh":"我以前没有去过那里。"},{"s":503.58,"e":509.36,"en":"I think we should get some beer and wine and some fruit juice and other soft drinks.","zh":"我觉得我们应该喝点啤酒葡萄酒、一些果汁和其他软饮料饮料。"},{"s":509.36,"e":510.4,"en":"What do you think?","zh":"你怎么认为？"},{"s":510.4,"e":511.46,"en":"Sounds great.","zh":"听起来不错。"},{"s":511.46,"e":513.92,"en":"I think those drinks will be enough.","zh":"我想这些饮料就足够了。"},{"s":513.92,"e":519.4,"en":"And I heard that the new supermarket offers some big discounts to attract customers.","zh":"我听说新超市提供一些大的折扣来吸引顾客。"},{"s":519.4,"e":522.24,"en":"So, going there should be a great idea.","zh":"所以，去那里应该是个好主意。"},{"s":522.24,"e":524.54,"en":"What should we do about music?","zh":"对于音乐我们该做些什么？"},{"s":524.54,"e":529.86,"en":"Maybe we should ask Paul to bring his computer and speakers so that we can play some music.","zh":"也许我们应该请保罗带上他的电脑和扬声器，以便我们能够播放一些音乐。"},{"s":529.86,"e":532.7,"en":"He has a great collection of different stuff.","zh":"他收藏了很多不同的东西。"},{"s":532.7,"e":534.88,"en":"Yes, all right.","zh":"是的，好的。"},{"s":534.88,"e":539.58,"en":"Questions 8 to 11 are based on the conversation you have just heard.","zh":"问题8至11基于您刚才听到的对话。"},{"s":539.58,"e":540.82,"en":"Question 8.","zh":"问题8."},{"s":540.82,"e":558.9,"en":"What are the speakers mainly talking about?","zh":"演讲者主要谈论什么？"},{"s":558.9,"e":560.52,"en":"Question 9.","zh":"问题9."},{"s":560.52,"e":581.6,"en":"Why does the woman say it is a good idea to serve foods that guests can help themselves to?","zh":"为什么女人说这是为客人提供可以帮助自己？"},{"s":581.6,"e":583.2,"en":"Question 10.","zh":"问题10."},{"s":583.2,"e":602.56,"en":"What does the woman say about the new supermarket?","zh":"女人对新事物有何看法超级市场？"},{"s":602.56,"e":604.04,"en":"Question 11.","zh":"问题11."},{"s":604.04,"e":622.43,"en":"What does the man suggest they ask Paul to do?","zh":"这个人建议他们问保罗什么做什么？"},{"s":622.43,"e":624.21,"en":"Conversation 2.","zh":"对话2。"},{"s":624.21,"e":626.91,"en":"I'm thinking of buying a car.","zh":"我正在考虑买一辆车。"},{"s":626.91,"e":633.55,"en":"I wouldn't need to use it every day, but I think it would be very convenient to have one for the weekends.","zh":"我不需要每天都使用它，但我认为这会很方便周末吃一个。"},{"s":633.55,"e":635.27,"en":"That's exciting.","zh":"这真令人兴奋。"},{"s":635.27,"e":637.41,"en":"Would this be your first car?","zh":"这会是你的第一辆车吗？"},{"s":637.41,"e":642.35,"en":"No, I actually owned a car for a little while when I lived in Miami.","zh":"不，我实际上有一辆汽车我在迈阿密居住过不久。"},{"s":642.35,"e":650.65,"en":"You see, in America, many cities don't have good public transport, so most people need their own car to get around.","zh":"你看，在美国，很多城市没有公共交通十分便利，因此大多数人都需要有自己的汽车出行。"},{"s":650.65,"e":652.15,"en":"I see.","zh":"我懂了。"},{"s":652.15,"e":656.25,"en":"So, have you got your mind set on a specific model?","zh":"那么，你是否已经下定决心具体型号？"},{"s":656.25,"e":657.91,"en":"No, not really.","zh":"不，不是真的。"},{"s":657.91,"e":665.35,"en":"I've heard that German cars are very reliable, but I haven't decided on a specific model yet.","zh":"我听说德国汽车非常可靠，但我还没决定具体型号然而。"},{"s":665.35,"e":670.05,"en":"I'd also like it to be small so that it's easy to drive in the city.","zh":"我也希望它小一点，这样在城市里驾驶很方便。"},{"s":670.05,"e":673.73,"en":"I have a friend who sells second-hand cars.","zh":"我有一个朋友卖二手汽车。"},{"s":673.73,"e":677.23,"en":"In fact, I think his family owns the business.","zh":"事实上，我认为他的家人拥有商业。"},{"s":677.23,"e":681.01,"en":"He's a really nice guy, and he knows a lot about cars.","zh":"他是个很好的人，他知道很多关于汽车的信息。"},{"s":681.01,"e":687.49,"en":"I could give you his phone number if you want, and you could call him and ask him questions.","zh":"我可以给你他的电话号码，如果你想要，你可以打电话给他问他问题。"},{"s":687.49,"e":693.29,"en":"That's nice of you, but I don't want to feel obliged to buy one of his cars.","zh":"你真好，但我不要觉得有义务买他的汽车。"},{"s":693.29,"e":695.45,"en":"Oh no, he's not like that.","zh":"哦不，他不是那样的。"},{"s":695.45,"e":700.63,"en":"He's a good friend of mine, and he would never try to pressure you or cheat you.","zh":"他是我的好朋友，他绝不会试图向你施压或欺骗你你。"},{"s":700.63,"e":704.87,"en":"Well, if you trust him, then I guess it should be okay.","zh":"嗯，如果你相信他，那么我想应该没问题。"},{"s":704.87,"e":711.31,"en":"To be honest, I could use some help in deciding what type of vehicle would best suit my needs.","zh":"说实话我需要一些帮助在决定哪种类型的车辆最适合适合我的需要。"},{"s":711.31,"e":714.33,"en":"Speaking to an expert would be a good idea.","zh":"和专家谈谈是个好主意主意。"},{"s":714.33,"e":715.45,"en":"Exactly.","zh":"确切地。"},{"s":715.45,"e":718.01,"en":"You have nothing to worry about.","zh":"你没什么可担心的。"},{"s":718.01,"e":722.09,"en":"He's a lovely guy, and he'll be happy to help.","zh":"他是个可爱的人，他会很高兴的来帮忙。"},{"s":722.09,"e":727.65,"en":"Questions 12 to 15 are based on the conversation you have just heard.","zh":"问题12至15基于您刚才听到的对话。"},{"s":727.65,"e":729.35,"en":"Question 12.","zh":"问题12."},{"s":729.35,"e":747.01,"en":"Why does the woman want to have a car?","zh":"为什么女人想要一个车？"},{"s":747.01,"e":748.79,"en":"Question 13.","zh":"问题13."},{"s":748.79,"e":767.22,"en":"What does the woman say about German cars?","zh":"这位女士对于德国汽车有何评价？"},{"s":767.22,"e":768.86,"en":"Question 14.","zh":"问题14."},{"s":768.86,"e":787.08,"en":"What does the man recommend the woman do?","zh":"男人建议女人做什么？"},{"s":787.08,"e":788.62,"en":"Question 15.","zh":"问题15."},{"s":788.62,"e":807.66,"en":"What do we learn about the man's friend from the conversation?","zh":"我们对这个男人的朋友了解多少从谈话中？"},{"s":807.66,"e":809.24,"en":"Section C.","zh":"C部分。"},{"s":809.24,"e":810.68,"en":"Directions.","zh":"方向。"},{"s":810.68,"e":813.82,"en":"In this section, you will hear three passages.","zh":"在这一部分中，您将听到三段文字。"},{"s":813.82,"e":818.16,"en":"At the end of each passage, you will hear three or four questions.","zh":"在每篇文章的结尾，你将听到三到四个问题。"},{"s":818.16,"e":822.22,"en":"Both the passage and the questions will be spoken only once.","zh":"文章和问题都将只讲过一次。"},{"s":822.22,"e":830.34,"en":"After you hear a question, you must choose the best answer from the four choices marked A, B, C, and D.","zh":"听完问题后你必须选择标记的四个选项中的最佳答案A、B、C和D。"},{"s":830.34,"e":836.6,"en":"Then mark the corresponding letter on answer sheet 1 with a single line through the centre.","zh":"然后在答题纸上标记相应的字母1一条线穿过中心。"},{"s":836.6,"e":838.52,"en":"Passage 1.","zh":"段落1。"},{"s":838.52,"e":842.0,"en":"Pigs are not native to North America.","zh":"猪并非北美洲本土动物。"},{"s":842.0,"e":848.96,"en":"They were first introduced to California by Spanish and Russian explorers and settlers many centuries ago.","zh":"它们最早是由西班牙人引入加利福尼亚的以及许多世纪以前的俄罗斯探险家和定居者。"},{"s":848.96,"e":854.38,"en":"In the early times, pigs were allowed to wander freely in search of food.","zh":"在早期，猪被允许自由地游荡寻找食物。"},{"s":854.38,"e":861.58,"en":"This practice also allowed many pigs to escape from farms and live in the wild, which became a problem.","zh":"这种做法也让很多猪逃走了来自农场并生活在野外，成为一个问题。"},{"s":861.58,"e":867.84,"en":"In fact, they're one of the most damaging invasive species on the continent.","zh":"事实上，它们是最具破坏性的非洲大陆上的入侵物种。"},{"s":867.84,"e":873.02,"en":"Wild pigs cause millions of dollars in crop damage yearly.","zh":"野猪造成数百万美元的农作物损失每年都会遭受损坏。"},{"s":873.02,"e":879.58,"en":"They also harbour dozens of diseases that threaten both humans and farm animals.","zh":"它们还携带着几十种威胁人类和农场动物。"},{"s":879.58,"e":886.48,"en":"Forest patches with wild pigs have been found to have considerably reduced plant and animal diversity.","zh":"发现有野猪出没的森林斑块植物和动物多样性大大减少。"},{"s":886.48,"e":897.44,"en":"In addition to either eating other animals or their food supply, wild pigs damage native habitats by rooting up grasses and rubbing on trees.","zh":"除了吃其他动物或野猪破坏了当地的栖息地通过连根拔起草并摩擦树木。"},{"s":897.44,"e":904.98,"en":"Their activities may also create opportunities for invasive plants to colonise these areas.","zh":"他们的活动也可能为入侵者创造机会植物在这些地区定居。"},{"s":904.98,"e":910.16,"en":"Wild pigs will eat almost anything containing calories.","zh":"野猪几乎会吃任何含有热量的东西。"},{"s":910.16,"e":916.86,"en":"Mice, deer, birds, snakes and frogs are among their victims.","zh":"老鼠、鹿、鸟、蛇和青蛙等他们的受害者。"},{"s":916.86,"e":925.46,"en":"They can also harm other wild species through indirect competition, rather than eating them or shrinking their food supply.","zh":"它们还会通过以下方式危害其他野生物种间接竞争，而不是吃掉它们或缩小他们的食物供应。"},{"s":925.46,"e":934.8,"en":"On one particular United States island, wild pigs themselves became an attractive food source for a species of mainland eagle.","zh":"在美国的一个岛屿上，野猪它们本身就成为了一种有吸引力的食物来源大陆鹰的一种。"},{"s":934.8,"e":941.42,"en":"The eagles began breeding on the island and also feeding on a species of native fox.","zh":"老鹰开始在岛上繁殖，也以一种本地狐狸为食。"},{"s":941.42,"e":1013.68,"en":"The foxes were almost wiped out completely.","zh":"狐狸几乎被彻底消灭了。"},{"s":1013.68,"e":1015.88,"en":"Passage 2.","zh":"段落2。"},{"s":1015.88,"e":1025.26,"en":"A pair of entrepreneurs are planning to build and launch a spacecraft that would carry and roast coffee beans in outer space.","zh":"一对企业家正计划建造并发射一艘载有在外太空烘焙咖啡豆。"},{"s":1025.26,"e":1033.26,"en":"The craft will use the heat of re-entry to roast coffee beans as they float inside it in a pressurised tank.","zh":"该飞行器将利用-烘焙漂浮的咖啡豆位于其内部的压力罐内。"},{"s":1033.26,"e":1039.56,"en":"The effect would be to roast the beans all over and produce perfect coffee.","zh":"效果是烘焙咖啡豆并生产出完美的咖啡。"},{"s":1039.56,"e":1057.82,"en":"The businessmen say that on Earth, beans can easily break apart and get burned in the roaster, but if gravity is removed, the beans float around in a heated oven, receive 360 degrees of evenly distributed heat and roast to near perfection.","zh":"商人们说，在地球上，豆子可以容易破碎并燃烧但如果重力消失，咖啡豆在加热的烤箱里漂浮，接受360度均匀分布的热量，烘烤至接近完美。"},{"s":1057.82,"e":1062.78,"en":"The spacecraft will reach a height of around 200 kilometres.","zh":"航天器将达到约200公里。"},{"s":1062.78,"e":1070.24,"en":"The beans would then be roasted in the heat generated by the craft's 20-minute re-entry into Earth's atmosphere.","zh":"然后将咖啡豆放入飞船20分钟辐射产生的热量—进入地球大气层。"},{"s":1070.24,"e":1076.28,"en":"Temperatures in the pressurised tank will be kept to around 200 degrees Celsius.","zh":"加压罐内的温度将保持到200摄氏度左右。"},{"s":1076.28,"e":1086.24,"en":"Once back on Earth, the planet's first space-roasted beans would be used to make coffee that would be sold for the first time in Dubai.","zh":"回到地球后，这颗星球上的第一个太空-烘焙过的咖啡豆将用来制作咖啡首次出售在迪拜。"},{"s":1086.24,"e":1089.02,"en":"This is where the pair's company is based.","zh":"这正是两人公司的所在地。"},{"s":1089.02,"e":1092.42,"en":"It is not clear how much they would charge for a cup.","zh":"目前尚不清楚他们愿意付出多大努力一杯收费。"},{"s":1092.42,"e":1100.8,"en":"Surprisingly, the space roaster concept, should it go ahead, will not be the first attempt to take coffee into space.","zh":"令人惊讶的是，太空烘焙机的概念应该未来，不会是第一次尝试把咖啡带入太空。"},{"s":1100.8,"e":1113.62,"en":"In 2015, two Italian companies collaborated on the construction of a similar type of spacecraft, which was the first coffee machine designed for use in space.","zh":"2015年，两家意大利公司合作开发建造一艘类似类型的航天器，是第一台设计用于在太空中。"},{"s":1113.62,"e":1119.24,"en":"Questions 19 to 21 are based on the passage you have just heard.","zh":"问题19至21基于您刚刚听到的段落。"},{"s":1119.24,"e":1121.18,"en":"Question 19.","zh":"问题19."},{"s":1121.18,"e":1139.16,"en":"What are a pair of entrepreneurs planning to do?","zh":"一对企业家计划做？"},{"s":1139.16,"e":1140.66,"en":"Question 20.","zh":"问题20."},{"s":1140.66,"e":1160.11,"en":"What does the passage say about coffee beans roasted on Earth?","zh":"这篇文章对咖啡豆做了什么描述在地球上烤吗？"},{"s":1160.11,"e":1161.97,"en":"Question 21.","zh":"问题21."},{"s":1161.97,"e":1180.82,"en":"What did the two Italian companies do in 2015?","zh":"这两家意大利公司在2015年？"},{"s":1180.82,"e":1182.52,"en":"Passage 3.","zh":"段落3。"},{"s":1182.52,"e":1187.78,"en":"In cold and snowy Alaska, there's a village called Tekotna.","zh":"在寒冷多雪的阿拉斯加，有一个村庄被称为Tekotna。"},{"s":1187.78,"e":1192.04,"en":"It has a population of a mere 49 souls.","zh":"人口仅有49灵魂。"},{"s":1192.04,"e":1201.14,"en":"Each March, this tiny village swells up in numbers because it is located in the middle of a race that takes place every year.","zh":"每年三月，这个小村庄都会涌现出数字，因为它位于中间每年都会举行的比赛。"},{"s":1201.14,"e":1212.0,"en":"It is a seven-day race called the Iditarod Trail, and participants stop at Tekotna for their obligatory 24-hour rest.","zh":"这是一场为期七天的比赛，被称为爱迪塔罗德小径，参赛者在Tekotna停留他们必须休息24小时。"},{"s":1212.0,"e":1217.74,"en":"Lucky for them, Tekotna is famous for its delicious fruit pies.","zh":"幸运的是，特科特纳以其美味的水果派。"},{"s":1217.74,"e":1227.48,"en":"Weeks before the competitors arrive, the residents of Tekotna start preparing for what is without question their biggest event of the year.","zh":"在参赛者到达的几周前，Tekotna开始为毫无疑问的事情做准备他们今年最大的活动。"},{"s":1227.48,"e":1235.84,"en":"The whole village chips in to help, including the kids, who end up developing their baking skills at an early age.","zh":"全村人都伸出了援手，包括孩子们最终发展了自己的烘焙技能小时候就培养技能。"},{"s":1235.84,"e":1246.6,"en":"The exhausted and hungry racers are greeted with delightful pies of all kinds, such as apple, orange, lemon, or banana.","zh":"疲惫又饥饿的选手们受到了各种美味的馅饼，比如苹果馅饼，橙子、柠檬或者香蕉。"},{"s":1246.6,"e":1251.54,"en":"They consume the pies as stomach-warming race fuel.","zh":"他们吃馅饼作为暖胃的食物燃料。"},{"s":1251.54,"e":1256.64,"en":"The toughness of the race allows for racers to eat pretty much whatever they want.","zh":"比赛的艰苦程度让赛车手吃任何他们想吃的东西。"},{"s":1256.64,"e":1259.16,"en":"The more calories, the better.","zh":"卡路里越多越好。"},{"s":1259.16,"e":1265.66,"en":"Tekotna has gained a reputation for its dessert-based hospitality since the 1970s.","zh":"Tekotna因其甜点而闻名自1970年代以来，我们一直致力于酒店业。"},{"s":1265.66,"e":1270.1,"en":"It started with one person, Jan Newton.","zh":"这一切都始于一个人，JanNewton。"},{"s":1270.1,"e":1276.54,"en":"Jan moved from Idaho with her husband in 1972 and opened a restaurant.","zh":"Jan和丈夫从爱达荷州搬来1972年开了一家餐馆。"},{"s":1276.54,"e":1284.48,"en":"Her rich and filling fruit pies quickly got the racers' attention, and the village gained some fame as a result.","zh":"她那丰盛的水果派很快就赛车手的注意，村庄也得到了一些从而名声大噪。"},{"s":1284.48,"e":1290.68,"en":"Proud residents then started to refer to Jan as Queen of Tekotna.","zh":"自豪的居民们开始将Jan担任特科特纳女王。"},{"s":1290.68,"e":1296.72,"en":"Questions 22 to 25 are based on the passage you have just heard.","zh":"问题22至25基于您刚刚听到的段落。"},{"s":1296.72,"e":1298.78,"en":"Question 22.","zh":"问题22."},{"s":1298.78,"e":1318.93,"en":"Why do a lot of people come to the village of Tekotna every March?","zh":"为什么很多人来每年三月都会去Tekotna村吗？"},{"s":1318.93,"e":1321.09,"en":"Question 23.","zh":"问题23."},{"s":1321.09,"e":1339.4,"en":"What is the village of Tekotna famous for?","zh":"特科特纳Tekotna村因什么而闻名？"},{"s":1339.4,"e":1341.36,"en":"Question 24.","zh":"问题24."},{"s":1341.36,"e":1359.73,"en":"Who comes to help with the event of the year?","zh":"谁来帮助解决今年？"},{"s":1359.73,"e":1362.05,"en":"Question 25.","zh":"问题25."},{"s":1362.05,"e":1380.28,"en":"What does the passage say about Jan Newton?","zh":"这篇文章是怎样评价简·牛顿的？"},{"s":1380.28,"e":1382.84,"en":"That's the end of Listening Comprehension.","zh":"听力理解到此结束。"}]},{"id":"2021-12-1","title":"2021年12月 第1套","audio":"listening/2021-12-1.ogg","duration":1409.65,"sentences":[{"s":0.88,"e":11.22,"en":"College English Test, Band 4, Part 2, Listening Comprehension, Section A, Directions.","zh":"大学英语四级考试第二部分听力理解，A部分，说明。"},{"s":11.22,"e":15.38,"en":"In this section, you will hear three news reports.","zh":"在本部分中，您将听到三则新闻報告。"},{"s":15.38,"e":20.64,"en":"At the end of each news report, you will hear two or three questions.","zh":"在每篇新闻报道结束时，你将会听到两三个问题。"},{"s":20.64,"e":25.0,"en":"Both the news report and the questions will be spoken only once.","zh":"新闻报道和问题都将只说一次。"},{"s":25.0,"e":35.02,"en":"After you hear a question, you must choose the best answer from the four choices marked A, B, C, and D.","zh":"听完问题后你必须选择标记的四个选项中的最佳答案A、B、C和D。"},{"s":35.02,"e":42.42,"en":"Then mark the corresponding letter on Answer Sheet 1 with a single line through the center.","zh":"然后在答题纸上标记相应的字母1一条线穿过中心。"},{"s":42.42,"e":44.14,"en":"News Report 1.","zh":"新闻报道1."},{"s":44.14,"e":52.44,"en":"United Airlines has apologized for mistakenly shipping an American family's pet dog thousands of miles in the wrong direction to Japan.","zh":"美国联合航空公司对错误运送美国家庭的宠物狗远赴千里去日本的方向错误。"},{"s":52.44,"e":63.56,"en":"The dog owners' beloved 10-year-old dog named Buddy took an unexpected 16-hour flight to Tokyo following a mix-up by the airline.","zh":"狗主人心爱的10岁狗狗名叫巴迪的男子意外乘坐了16小时的飞机前往东京，因为航空公司。"},{"s":63.56,"e":67.82,"en":"The dog owners' family are currently in the process of moving.","zh":"狗主人一家目前移動的過程。"},{"s":67.82,"e":74.18,"en":"They were meant to be reunited with the pet in their new home city in Texas.","zh":"他们本应与他们在德克萨斯州的新家乡养了宠物。"},{"s":74.18,"e":83.28,"en":"But when they arrived at the United Airlines cargo facility in the southern U.S. state, they found a stranger's dog waiting in Buddy's place.","zh":"但当他们到达联合航空公司时美国南部州的货运设施，他们发现一只陌生人的狗在巴迪家等着地方。"},{"s":83.28,"e":94.2,"en":"Both of the dogs had been sent to the wrong destinations on connecting flights from Denver, with Buddy mistakenly being sent to Japan instead.","zh":"两只狗都被送往从丹佛出发的转机航班目的地错误，巴迪却被错误地派往了日本。"},{"s":94.2,"e":99.28,"en":"Buddy was given a physical check-up when he arrived at Tokyo's International Airport.","zh":"Buddy接受身体检查时他抵达东京国际机场。"},{"s":99.28,"e":104.62,"en":"The dog was then sent back to the U.S. on a private charter jet.","zh":"随后，这只狗被送回乘坐私人包机前往美国。"},{"s":104.62,"e":110.58,"en":"I'm so glad he's alive and coming home soon, said the relieved dog owner.","zh":"我很高兴他还活着并回家了很快，”松了一口气的狗主人说道。"},{"s":110.58,"e":114.02,"en":"An error occurred during the connections in Denver.","zh":"丹佛的连接过程中出现了错误。"},{"s":114.02,"e":118.44,"en":"We have notified our customers that their pets arrived safely.","zh":"我们已经通知我们的客户，他们的宠物安全抵达。"},{"s":118.44,"e":125.04,"en":"We will arrange to return the pets to them as soon as possible, a spokesperson of United Airlines said.","zh":"我们将安排将宠物送回尽快通知他们，美国联合航空表示。"},{"s":125.04,"e":130.62,"en":"Questions 1 and 2 are based on the news report you have just heard.","zh":"问题1和问题2基于您刚刚听到的新闻报道。"},{"s":130.62,"e":132.1,"en":"Question 1.","zh":"问题1."},{"s":132.1,"e":150.64,"en":"What does the news report say about United Airlines?","zh":"新闻报道对美联航有何评论航空公司？"},{"s":150.64,"e":152.5,"en":"Question 2.","zh":"问题2."},{"s":152.5,"e":173.03,"en":"What did the spokesperson for United Airlines say they would do after the incident?","zh":"美联航发言人怎么说事发之后他们会做什么？"},{"s":173.03,"e":175.07,"en":"News Report 2.","zh":"新闻报道2."},{"s":175.07,"e":180.71,"en":"Officials at Reid Park Zoo in Tucson, Arizona are celebrating the birth of a baby elephant.","zh":"亚利桑那州图森市里德公园动物园的官员正在庆祝一头小象的诞生。"},{"s":180.71,"e":185.31,"en":"Zoo officials say the baby was born on Monday.","zh":"动物园官员称，小熊猫出生在周一。"},{"s":185.31,"e":189.93,"en":"It is a female and she weighs nearly 130 kilograms.","zh":"这是一只雌性，体重接近130公斤。"},{"s":189.93,"e":194.45,"en":"Semba, her mother, is a 30-year-old African elephant.","zh":"她的母亲Semba是一位30岁非洲象。"},{"s":194.45,"e":197.63,"en":"The pregnancy lasted 22 months.","zh":"妊娠持续了22个月。"},{"s":197.63,"e":203.09,"en":"Officials describe the baby elephant as healthy, standing and nursing.","zh":"官员们称这只小象身体健康，站立和护理。"},{"s":203.09,"e":206.03,"en":"The baby hasn't been given a name yet.","zh":"婴儿还没有名字。"},{"s":206.03,"e":207.73,"en":"Semba has given birth before.","zh":"Semba以前也生过孩子。"},{"s":207.73,"e":215.89,"en":"Zoo officials said during this pregnancy she was closely monitored through physical exams and blood tests.","zh":"动物园官员表示，她在怀孕期间通过身体检查和血液测试密切监测。"},{"s":215.89,"e":221.49,"en":"Dr. Sue Tagielski is the zoo's director of zoological operations.","zh":"SueTagielski博士是动物园的动物学作业。"},{"s":221.49,"e":227.19,"en":"She said the elephant's birth went smoothly and that there were no complications.","zh":"她说大象的出生很顺利，没有任何并发​​症。"},{"s":227.19,"e":231.05,"en":"The new baby expands the zoo's elephant herd to six.","zh":"这只新生的大象扩大了动物园大象群的规模到六。"},{"s":231.05,"e":236.31,"en":"That includes the baby's parents, a sister, a brother and an adult female.","zh":"其中包括婴儿的父母、一个姐妹、一个兄弟和一名成年女性。"},{"s":236.31,"e":242.77,"en":"Questions 3 and 4 are based on the news report you have just heard.","zh":"问题3和问题4基于您刚刚听到的新闻报道。"},{"s":242.77,"e":244.43,"en":"Question 3.","zh":"问题3."},{"s":244.43,"e":262.88,"en":"What do we learn about the mother elephant Semba?","zh":"我们对母象了解多少森巴？"},{"s":262.88,"e":264.48,"en":"Question 4.","zh":"问题4."},{"s":264.48,"e":283.72,"en":"What does the report say about the birth of the new baby elephant?","zh":"报告对出生有何评价新生的小象呢？"},{"s":283.72,"e":285.64,"en":"News Report 3.","zh":"新闻报道3."},{"s":285.64,"e":290.12,"en":"Three years ago, a couple was enjoying a meal at a beach restaurant.","zh":"三年前，一对夫妇正在享受在海滩餐厅用餐。"},{"s":290.12,"e":294.28,"en":"The restaurant was built on a wooden structure above the seawater.","zh":"餐厅采用木结构建造在海水之上。"},{"s":294.28,"e":299.56,"en":"During the meal, the man's wedding ring slipped off his finger.","zh":"吃饭时，男人的结婚戒指滑落他的手指上。"},{"s":299.56,"e":304.1,"en":"It fell through the wooden floorboards, apparently lost forever.","zh":"它从木地板上掉下来了，显然是丢了永远。"},{"s":304.1,"e":309.62,"en":"Recently, the restaurant manager, Ryan Cravoy, decided to replace the wooden deck.","zh":"最近，餐厅经理RyanCravoy决定更换木甲板。"},{"s":309.62,"e":317.6,"en":"And he found an old gold coin, some $100 bills and a silver wedding ring while replacing the deck.","zh":"他发现了一枚古老的金币，100美元钞票和一枚银结婚戒指更换甲板。"},{"s":317.6,"e":322.62,"en":"The restaurant's waitress, Sasha Formica, posted a picture of the ring on Facebook.","zh":"该餐厅的女服务员SashaFormica发布了一张照片在Facebook上发布了这枚戒指。"},{"s":322.62,"e":326.94,"en":"The post was shared about 5,000 times.","zh":"该帖子已被分享约5,000次。"},{"s":326.94,"e":330.9,"en":"Three days later, the happy wife called to claim the ring.","zh":"三天后，妻子高兴地打电话来领取戒指。"},{"s":330.9,"e":337.72,"en":"She even texted pictures of her and her husband eating there in 2017 as proof.","zh":"她甚至发短信给她和她的丈夫于2017年在那里吃饭作为证明。"},{"s":337.72,"e":341.36,"en":"The restaurant mailed the ring back to the happy couple.","zh":"餐厅将戒指寄回幸福的一对。"},{"s":341.36,"e":346.2,"en":"Meanwhile, Cravoy discovered that the gold coin was very rare.","zh":"与此同时，克拉沃伊发现这枚金币非常罕见。"},{"s":346.2,"e":351.58,"en":"It was from 1855 and worth as much as $2,000.","zh":"这是1855年的，价值为2,000美元。"},{"s":351.58,"e":357.92,"en":"Questions 5 to 7 are based on the news report you have just heard.","zh":"问题5至7基于您刚刚听到的新闻报道。"},{"s":357.92,"e":359.62,"en":"Question 5.","zh":"问题5."},{"s":359.62,"e":376.89,"en":"What do we learn about the restaurant?","zh":"我们对这家餐厅了解了什么？"},{"s":376.89,"e":378.27,"en":"Question 6.","zh":"问题6."},{"s":378.27,"e":397.14,"en":"What did the restaurant manager decide to do recently?","zh":"餐厅经理决定做什么最近？"},{"s":397.14,"e":398.74,"en":"Question 7.","zh":"问题7."},{"s":398.74,"e":416.96,"en":"What did the waitress do about the recovered ring?","zh":"女服务员对康复的人做了什么戒指？"},{"s":416.96,"e":418.48,"en":"Section B.","zh":"B部分。"},{"s":418.48,"e":419.76,"en":"Directions.","zh":"方向。"},{"s":419.76,"e":423.44,"en":"In this section, you will hear two long conversations.","zh":"在本节中，你将听到两个长对话。"},{"s":423.44,"e":428.84,"en":"At the end of each conversation, you will hear four questions.","zh":"每次对话结束时，你将听四个问题。"},{"s":428.84,"e":433.38,"en":"Both the conversation and the questions will be spoken only once.","zh":"对话和问题都将只讲过一次。"},{"s":433.38,"e":442.66,"en":"After you hear a question, you must choose the best answer from the four choices marked A, B, C, and D.","zh":"听完问题后你必须选择标记的四个选项中的最佳答案A、B、C和D。"},{"s":442.66,"e":449.26,"en":"Then mark the corresponding letter on Answer Sheet 1 with a single line through the center.","zh":"然后在答题纸上标记相应的字母1一条线穿过中心。"},{"s":449.26,"e":451.08,"en":"Conversation 1.","zh":"对话1。"},{"s":451.08,"e":456.36,"en":"I can't believe that duck hunting is still legal in so many parts of the world.","zh":"我不敢相信鸭子狩猎仍然在世界许多地方都是合法的。"},{"s":456.36,"e":465.44,"en":"The scientific evidence from countries like Australia, Canada, and the USA clearly indicates a decline in the birds' numbers.","zh":"来自澳大利亚、加拿大等国家的科学证据美国明显显示出鸟类的数量。"},{"s":465.44,"e":472.14,"en":"But can anyone be sure if the decline is really caused by the hunting or by climate change?","zh":"但有谁能确定下降趋势确实是由于狩猎或气候变化？"},{"s":472.14,"e":474.2,"en":"It's caused by both, in fact.","zh":"事实上，这是两者共同造成的。"},{"s":474.2,"e":478.34,"en":"We see more droughts in countries like Australia.","zh":"我们看到澳大利亚等国家出现更多干旱。"},{"s":478.34,"e":484.04,"en":"Ducks are birds that feed and breed in areas where there is a lot of water.","zh":"鸭子是在水多的地区。"},{"s":484.04,"e":489.54,"en":"But their habitats have been shrinking in recent decades because of the droughts.","zh":"但近年来它们的栖息地一直在缩小几十年来，干旱一直持续。"},{"s":489.54,"e":495.44,"en":"And I guess with fewer places to inhabit, they concentrate in greater numbers in fewer areas.","zh":"我想，随着居住的地方越来越少，它们在更少的地区集中更多的数量。"},{"s":495.44,"e":499.0,"en":"Which surely makes them easier targets for the hunters.","zh":"这无疑使他们更容易成为猎人。"},{"s":499.0,"e":500.24,"en":"It does.","zh":"是的。"},{"s":500.24,"e":501.96,"en":"My grandfather was a duck hunter.","zh":"我的祖父是一名鸭子猎人。"},{"s":501.96,"e":507.24,"en":"He told me hunting ducks and geese began in the 19th century.","zh":"他告诉我，打猎鸭子和鹅始于在19世纪。"},{"s":507.24,"e":515.26,"en":"They were an easily found and plentifully available food source in farming areas, especially for poor immigrants.","zh":"它们很容易找到，而且供应充足农业地区的食物来源，特别是对于贫困人口移民。"},{"s":515.26,"e":518.34,"en":"What did they use for hunting during that period?","zh":"当时他们用什么来打猎时期？"},{"s":518.34,"e":523.58,"en":"They used new types of guns, and birds could easily be shot down in flight.","zh":"他们使用了新型枪支和鸟类很容易在飞行中被击落。"},{"s":523.58,"e":529.04,"en":"And in such great numbers that commercial hunting of ducks and geese became an industry.","zh":"数量如此之多，商业狩猎养鸭和养鹅已成为一种产业。"},{"s":529.04,"e":533.58,"en":"Yet there's no commercial farming of these birds nowadays.","zh":"然而，这些鸟类并没有被商业化养殖如今。"},{"s":533.58,"e":537.32,"en":"Their meat is hardly eaten in Western countries.","zh":"西方国家几乎没人吃它们的肉。"},{"s":537.32,"e":538.04,"en":"No.","zh":"不。"},{"s":538.04,"e":542.86,"en":"Duck hunting seemingly exists as the continuation of a tradition.","zh":"鸭子狩猎似乎是为了延续一种传统。"},{"s":542.86,"e":549.84,"en":"Wild ducks have never been popular with farmers like my grandfather anyway, because they sometimes destroy crops.","zh":"野鸭从未受到农民的欢迎就像我的祖父一样，因为他们有时会破坏农作物。"},{"s":549.84,"e":553.58,"en":"In fact, farmers use to poison them in large numbers.","zh":"事实上，农民们习惯于用毒药大量的。"},{"s":553.58,"e":556.14,"en":"That somehow doesn't surprise me.","zh":"这并不令我感到惊讶。"},{"s":556.14,"e":562.4,"en":"Nobody places much value on the lives of these poor birds or on their meat.","zh":"没有人会重视这些可怜的鸟或它们的肉。"},{"s":562.4,"e":568.58,"en":"Questions 8 to 11 are based on the conversation you have just heard.","zh":"问题8至11基于您刚才听到的对话。"},{"s":568.58,"e":570.08,"en":"Question 8.","zh":"问题8."},{"s":570.08,"e":587.9,"en":"What does the woman find unbelievable?","zh":"女人觉得什么难以置信呢？"},{"s":587.9,"e":589.54,"en":"Question 9.","zh":"问题9."},{"s":589.54,"e":610.02,"en":"What does the woman say has caused the shrinking of ducks' habitats in Australia?","zh":"女人说了什么导致了澳大利亚鸭子的栖息地正在缩小？"},{"s":610.02,"e":611.56,"en":"Question 10.","zh":"问题10."},{"s":611.56,"e":631.57,"en":"Why is there no commercial farming of ducks and geese in Western countries?","zh":"为什么没有商业化养殖鸭子西方国家也有鹅吗？"},{"s":631.57,"e":633.15,"en":"Question 11.","zh":"问题11."},{"s":633.15,"e":652.35,"en":"What does the woman say about farmers in her grandfather's time?","zh":"女人对农民说了什么她祖父的时代？"},{"s":652.35,"e":654.21,"en":"Conversation 2.","zh":"对话2。"},{"s":654.21,"e":655.43,"en":"OK, Miss Bright.","zh":"好的，Bright小姐。"},{"s":655.43,"e":657.49,"en":"I've finished calculating.","zh":"我已經計算完了。"},{"s":657.49,"e":664.21,"en":"I estimate you have between 210 and 240 square metres of walls and ceiling.","zh":"我估计你有210到240个平方米的墙壁和天花板。"},{"s":664.21,"e":666.97,"en":"So, how much would the paint job cost?","zh":"那么，油漆工作要花多少钱？"},{"s":666.97,"e":671.21,"en":"That would depend on the quality of paint you choose.","zh":"这取决于油漆的质量你选择。"},{"s":671.21,"e":673.19,"en":"We carry two brands.","zh":"我们有两个品牌。"},{"s":673.19,"e":678.55,"en":"One costs 60 cents every square metre and the other 90 cents.","zh":"每平方米60美分，剩下的90美分。"},{"s":678.55,"e":687.61,"en":"The second is guaranteed to look great for about 10 years, whereas the cheaper one will start to dull after around 6 or 7 years.","zh":"第二个肯定看起来很棒大约10年，而较便宜的大约6点或7点后开始变钝年。"},{"s":687.61,"e":691.79,"en":"In that case, we would prefer the more expensive option.","zh":"在这种情况下，我们更希望昂贵的选择。"},{"s":691.79,"e":693.83,"en":"Alright then.","zh":"好吧。"},{"s":693.83,"e":700.51,"en":"So, including labour costs, taxes and everything, this job would come to $3,000.","zh":"因此，包括劳动力成本、税收和所有费用，这份工作的收入将达到3,000美元。"},{"s":700.51,"e":701.53,"en":"Hmm.","zh":"唔。"},{"s":701.53,"e":706.21,"en":"To be perfectly honest, that's more than I expected.","zh":"说实话，这比我预期的。"},{"s":706.21,"e":713.51,"en":"Please bear in mind that the price includes moving all the furniture and the whole task would take two days.","zh":"请注意，价格包括搬动所有家具和整个任务需要两天时间。"},{"s":713.51,"e":714.37,"en":"Really?","zh":"真的吗？"},{"s":714.37,"e":715.45,"en":"Why?","zh":"为什么？"},{"s":715.45,"e":724.51,"en":"Well, we can't paint the walls without clearing all the furniture first, so every time we paint a room, we first have to move the furniture to another room.","zh":"嗯，我们不能不清理就粉刷墙壁先把所有的家具都摆上，所以每次我们粉刷房间，我们首先要搬家把家具搬到另一个房间。"},{"s":724.51,"e":726.57,"en":"So that takes more time.","zh":"所以这需要更多时间。"},{"s":726.57,"e":730.61,"en":"Plus it requires two people, which works out more expensive.","zh":"另外，它需要两个人，更贵。"},{"s":730.61,"e":731.77,"en":"I see.","zh":"我懂了。"},{"s":731.77,"e":736.83,"en":"But does that mean I could not live here in my own house during those two days?","zh":"但这是否意味着我无法活下去在那两次天？"},{"s":736.83,"e":738.61,"en":"That is correct.","zh":"正确。"},{"s":738.61,"e":739.71,"en":"Oh well.","zh":"那好吧。"},{"s":739.71,"e":742.27,"en":"That changes everything, I'm afraid.","zh":"我担心那会改变一切。"},{"s":742.27,"e":745.83,"en":"I would have to stay with a friend or check into a hotel.","zh":"我必须和朋友住在一起或入住酒店。"},{"s":745.83,"e":748.05,"en":"I hadn't considered any of that.","zh":"我之前根本没考虑过这些。"},{"s":748.05,"e":755.11,"en":"I'm starting to realize that painting my house is far more troublesome than I had anticipated.","zh":"我开始意识到粉刷我的房子比我预想的要麻烦得多。"},{"s":755.11,"e":757.11,"en":"This is usually the case.","zh":"通常情况都是这样的。"},{"s":757.11,"e":760.55,"en":"Most of our clients go through the same realization.","zh":"我们的大多数客户都经历过同样的实现。"},{"s":760.55,"e":761.93,"en":"I see.","zh":"我懂了。"},{"s":761.93,"e":763.43,"en":"You have my number.","zh":"你有我的电话号码。"},{"s":763.43,"e":767.45,"en":"Please feel free to call me for any further questions.","zh":"如有任何疑问，请随时给我打电话进一步的问题。"},{"s":767.45,"e":768.59,"en":"Thank you.","zh":"谢谢。"},{"s":768.59,"e":773.77,"en":"Questions 12 to 15 are based on the conversation you have just heard.","zh":"问题12至15基于您刚才听到的对话。"},{"s":773.77,"e":775.25,"en":"Question 12.","zh":"问题12."},{"s":775.25,"e":791.75,"en":"What is the woman planning to do?","zh":"女人到底想干什么？"},{"s":791.75,"e":793.95,"en":"Question 13.","zh":"问题13."},{"s":793.95,"e":811.48,"en":"What is the woman's chief concern?","zh":"女人最关心的是什么？"},{"s":811.48,"e":813.0,"en":"Question 14.","zh":"问题14."},{"s":813.0,"e":832.28,"en":"What does the woman have to do while the paint job is being done?","zh":"女人要做什么油漆工作正在进行吗？"},{"s":832.28,"e":833.9,"en":"Question 15.","zh":"问题15."},{"s":833.9,"e":853.39,"en":"What has the woman come to realize at the end of the conversation?","zh":"女人意识到了什么谈话结束了吗？"},{"s":853.39,"e":854.93,"en":"Section C.","zh":"C部分。"},{"s":854.93,"e":856.25,"en":"Directions.","zh":"方向。"},{"s":856.25,"e":859.89,"en":"In this section, you will hear three passages.","zh":"在这一部分中，您将听到三段文字。"},{"s":859.89,"e":864.21,"en":"At the end of each passage, you will hear three or four questions.","zh":"在每篇文章的结尾，你将听到三到四个问题。"},{"s":864.21,"e":869.23,"en":"Both the passage and the questions will be spoken only once.","zh":"文章和问题都将只讲过一次。"},{"s":869.23,"e":878.63,"en":"After you hear a question, you must choose the best answer from the four choices marked A, B, C and D.","zh":"听完问题后你必须选择标记的四个选项中的最佳答案A、B、C和D。"},{"s":878.63,"e":885.73,"en":"Then mark the corresponding letter on Answer Sheet 1 with a single line through the center.","zh":"然后在答题纸上标记相应的字母1一条线穿过中心。"},{"s":885.73,"e":887.35,"en":"Passage 1.","zh":"段落1。"},{"s":887.35,"e":896.29,"en":"Homework is an important part of schooling, but the purposes of giving children homework will change as they grow older.","zh":"家庭作业是学校教育的重要组成部分，但是给孩子布置家庭作业的目的将会改变随着他们长大。"},{"s":896.29,"e":905.41,"en":"At the primary level, the main aim is to cultivate good habits, like learning to plan and exercising self-discipline.","zh":"在小学阶段，主要目标是培养良好的习惯，比如学会计划并加强自律。"},{"s":905.41,"e":916.65,"en":"During the secondary school years, extending what is learned at school is positively related to academic achievement, so the content of homework becomes more important.","zh":"在中学阶段，延长在学校学到的知识与学业成绩呈正相关成绩，所以家庭作业的内容变得更加重要的。"},{"s":916.65,"e":920.53,"en":"So how can you help your child do their best?","zh":"那么你怎样才能帮助你的孩子他们最好的？"},{"s":920.53,"e":926.89,"en":"Creating an ideal working environment will make it easier for them to get down to their assignments quickly.","zh":"创造理想的工作环境将使让他们更容易地投入到他们的快速完成作业。"},{"s":926.89,"e":937.69,"en":"Make sure it's free of distractions, and for primary school children at least, somewhere near you, so you can answer questions and offer encouragement.","zh":"确保没有干扰，并且至少在你附近某个地方的小学生，这样你就可以回答问题并提供鼓励。"},{"s":937.69,"e":947.37,"en":"You'll probably have to help younger children plan their session, but it's important that by the end of primary school, it's second nature.","zh":"你可能必须帮助年幼的孩子计划他们的会议，但重要的是，小学毕业后，它就成了第二天性。"},{"s":947.37,"e":954.97,"en":"Get them to tell you everything they have to do, then encourage them to establish an order in which they do work.","zh":"让他们告诉你他们所拥有的一切然后鼓励他们建立一个他们工作的顺序。"},{"s":954.97,"e":962.57,"en":"When there's several different assignments, make sure they begin with one they enjoy, so it seems easy to get started.","zh":"当有几项不同的任务时，确保它们从他们喜欢的开始，所以看起来容易上手。"},{"s":962.57,"e":971.25,"en":"It's best to take on the most difficult task second, once they're settled, but before they get tired.","zh":"最好接受最困难的事情第二项任务，一旦他们安顿下来，但在他们累了。"},{"s":971.25,"e":978.81,"en":"If older children have more than an hour of homework, encourage them to schedule a short break to stretch.","zh":"如果年龄较大的孩子有超过一小时的家庭作业，鼓励他们安排一个简短的休息一下，伸展一下。"},{"s":978.81,"e":992.57,"en":"If you encourage them to tell you what they've learned, they'll absorb the information more deeply and remember it more readily.","zh":"如果你鼓励他们告诉你什么他们将会更深入地吸收信息并且更容易记住。"},{"s":992.57,"e":994.55,"en":"Question 16.","zh":"问题16."},{"s":994.55,"e":1014.06,"en":"What is the main aim of homework for primary school kids?","zh":"家庭作业的主要目的是什么小学生？"},{"s":1014.06,"e":1015.68,"en":"Question 17.","zh":"问题17."},{"s":1015.68,"e":1034.67,"en":"What does the passage suggest parents do to help their children?","zh":"文章建议父母做什么来帮助他们的孩子？"},{"s":1034.67,"e":1036.29,"en":"Question 18.","zh":"问题18."},{"s":1036.29,"e":1055.38,"en":"What should children do to deal with multiple assignments?","zh":"孩子应该如何应对多重任务？"},{"s":1055.38,"e":1056.98,"en":"Passage 2.","zh":"段落2。"},{"s":1056.98,"e":1067.1,"en":"Workers at Mexican Oil Company will receive a health incentive of almost $300 a year if they meet certain body weight standards.","zh":"墨西哥石油公司的工人将获得每年近300美元的健康奖励，如果他们符合一定的体重标准。"},{"s":1067.1,"e":1071.52,"en":"To qualify for the bonus, they must maintain a healthy weight.","zh":"要获得奖金，他们必须保持健康的体重。"},{"s":1071.52,"e":1079.54,"en":"For those who are overweight or obese, they can receive the bonus if they reduce their weight by 10% during the year.","zh":"对于那些超重或肥胖的人来说，他们如果他们减少年内减轻体重10%。"},{"s":1079.54,"e":1090.24,"en":"Some applaud the policy as fair because it rewards both individuals who maintain a healthy weight and those who are working towards achieving it.","zh":"一些人称赞该政策公平，因为奖励那些保持健康体重的人以及那些为实现这一目标而努力的人们。"},{"s":1090.24,"e":1101.8,"en":"But critics say the policy contradicts recommendations by many health experts, who warn that a person's weight is influenced by genetic and environmental factors.","zh":"但批评人士表示，该政策与许多健康专家警告说，一个人的体重受遗传和环境因素的影响。"},{"s":1101.8,"e":1107.7,"en":"That means weight can be hard for individuals to control, which makes the bonus unfair.","zh":"这意味着体重对于个人来说可能很难控制，这使得奖金变得不公平。"},{"s":1107.7,"e":1116.62,"en":"Some experts say the policy is inconsistent with the science of what we know about body weight regulation.","zh":"一些专家表示，该政策不符合我们所知的身体科学体重调节。"},{"s":1116.62,"e":1121.3,"en":"These experts argue that focusing on weight is the wrong approach.","zh":"这些专家认为，关注体重是错误的方法。"},{"s":1121.3,"e":1127.96,"en":"A more productive method of encouraging health among employees is to promote healthy behaviors.","zh":"促进健康的更有效方法员工的根本目的是促进健康行为。"},{"s":1127.96,"e":1136.44,"en":"For example, companies can give workers gym memberships or encourage participation in lectures on healthy eating and living.","zh":"例如，公司可以为员工提供健身会员资格或鼓励参加健康饮食讲座和生活。"},{"s":1136.44,"e":1144.58,"en":"They can also reduce sweets and provide healthier snacks in the office and healthier meals at the company canteen.","zh":"它们还可以减少甜食，提供更健康的办公室里的零食和更健康的膳食公司食堂。"},{"s":1144.58,"e":1149.76,"en":"Or they can give employees more time during their lunch break to exercise.","zh":"或者他们可以在午休时间锻炼身体。"},{"s":1149.76,"e":1157.32,"en":"These are much better and much more productive ways for companies to move forward on their employees' well-being.","zh":"这些更好，更高效企业继续前进的方式员工的福祉。"},{"s":1157.32,"e":1161.54,"en":"Questions 19 to 21 are based on the passage you have just heard.","zh":"问题19至21基于您刚刚听到的段落。"},{"s":1161.54,"e":1163.74,"en":"Question 19.","zh":"问题19."},{"s":1163.74,"e":1182.53,"en":"Who will qualify for the bonus in Mexican oil company?","zh":"谁有资格获得墨西哥奖金石油公司？"},{"s":1182.53,"e":1184.11,"en":"Question 20.","zh":"问题20."},{"s":1184.11,"e":1203.73,"en":"What do critics think of Mexican oil company's bonus policy?","zh":"评论家如何看待墨西哥石油公司的奖金政策？"},{"s":1203.73,"e":1205.47,"en":"Question 21.","zh":"问题21."},{"s":1205.47,"e":1224.98,"en":"What do experts propose companies do about workers' well-being?","zh":"专家建议公司如何应对工人的福利？"},{"s":1224.98,"e":1226.68,"en":"Passage 3.","zh":"段落3。"},{"s":1226.68,"e":1234.34,"en":"Campaigners have warned that the British government is not doing enough to prevent left-handed pupils from falling behind their peers.","zh":"活动人士警告称，英国政府在预防左撇子学生方面做得不够避免落后于同龄人。"},{"s":1234.34,"e":1240.44,"en":"They claim that thousands of children are still being penalized for being left-handed.","zh":"他们声称，仍有数千名儿童因是左撇子而受到惩罚。"},{"s":1240.44,"e":1247.78,"en":"This is due to a lack of action from ministers who have failed to take any meaningful action for years.","zh":"这是由于缺乏行动未能采取任何行动的部长多年来有意义的行动。"},{"s":1247.78,"e":1259.9,"en":"It is feared that a failure to address early year challenges, such as poor handwriting, leads to much more serious problems down the line with these pupils facing reduced career prospects.","zh":"人们担心，如果不能解决早期面临的挑战，例如书写不规范，导致导致更严重的问题这些学生面临的职业前景较差。"},{"s":1259.9,"e":1271.4,"en":"Studies in recent years show that left-handed children are more likely to suffer with learning difficulties and their scores are lower on IQ tests.","zh":"近年来的研究表明，左撇子儿童更有可能学习困难困难，智商得分较低測試。"},{"s":1271.4,"e":1278.88,"en":"Campaigners feel it's strange that children in British schools are penalized because they happen to be left-handed.","zh":"活动人士认为，英国儿童学校受到惩罚，因为他们恰好左撇子。"},{"s":1278.88,"e":1283.82,"en":"They don't understand why successive governments have failed to act on this.","zh":"他们不明白为什么历届政府都失败了并采取行动。"},{"s":1283.82,"e":1295.64,"en":"They want the Department of Education to record which children are left-handed and what their educational attainments are, since they make up some 10% of the population.","zh":"他们希望教育部记录哪些孩子是左撇子，他们的教育水平是10%的人口。"},{"s":1295.64,"e":1302.78,"en":"In early year education, left-handed children are struggling and making a mess of their handwriting.","zh":"在早期教育中，左撇子儿童挣扎并弄乱了他们的笔迹。"},{"s":1302.78,"e":1306.06,"en":"Educators don't know how to deal with this.","zh":"教育工作者不知道该如何处理这个问题。"},{"s":1306.06,"e":1310.5,"en":"In many cases, there's no active help and a lack of teacher training.","zh":"在许多情况下，没有主动的帮助和缺乏教师培训。"},{"s":1310.5,"e":1317.16,"en":"Campaigners point out that a high percentage of the prison population is left-handed.","zh":"活动人士指出，监狱里的囚犯都是左撇子。"},{"s":1317.16,"e":1324.16,"en":"They say that these prison numbers are unusually high and ask why it is the case.","zh":"他们说，这些囚犯人数异常并询问为什么会这样。"},{"s":1324.16,"e":1330.06,"en":"Questions 22 to 25 are based on the passage you have just heard.","zh":"问题22至25基于您刚刚听到的段落。"},{"s":1330.06,"e":1331.72,"en":"Question 22.","zh":"问题22."},{"s":1331.72,"e":1350.12,"en":"Why are some people criticizing the British government?","zh":"为什么有些人批评英国政府？"},{"s":1350.12,"e":1352.22,"en":"Question 23.","zh":"问题23."},{"s":1352.22,"e":1371.55,"en":"What do studies in recent years show about left-handed children?","zh":"近年来的研究表明左撇子儿童？"},{"s":1371.55,"e":1373.33,"en":"Question 24.","zh":"问题24."},{"s":1373.33,"e":1392.75,"en":"What do the campaigners demand the Department of Education do?","zh":"活动人士要求教育部教育干什么？"},{"s":1392.75,"e":1394.81,"en":"Question 25.","zh":"问题25."},{"s":1394.81,"e":1409.65,"en":"What do the campaigners want to know about left-handed prisoners?","zh":"活动家们想知道什么左撇子囚犯？"}]},{"id":"2022-12-1","title":"2022年12月 第1套","audio":"listening/2022-12-1.ogg","duration":1411.45,"sentences":[{"s":0.14,"e":9.8,"en":"College English Test, Band 4, Part 2, Listening Comprehension, Section A, Directions.","zh":"大学英语四级考试第二部分听力理解，A部分，说明。"},{"s":9.8,"e":13.54,"en":"In this section, you will hear three news reports.","zh":"在本部分中，您将听到三则新闻報告。"},{"s":13.54,"e":18.24,"en":"At the end of each news report, you will hear two or three questions.","zh":"在每篇新闻报道结束时，你将会听到两三个问题。"},{"s":18.24,"e":22.46,"en":"Both the news report and the questions will be spoken only once.","zh":"新闻报道和问题都将只说一次。"},{"s":22.46,"e":31.48,"en":"After you hear a question, you must choose the best answer from the four choices marked A, B, C, and D.","zh":"听完问题后你必须选择标记的四个选项中的最佳答案A、B、C和D。"},{"s":31.48,"e":38.44,"en":"Then mark the corresponding letter on Answer Sheet 1 with a single line through the center.","zh":"然后在答题纸上标记相应的字母1一条线穿过中心。"},{"s":38.44,"e":40.64,"en":"News Report 1.","zh":"新闻报道1."},{"s":40.64,"e":50.84,"en":"Operations at one of Australia's largest gold mines had to be temporarily suspended on Friday after a partial wall collapse at one of the mine's dams.","zh":"澳大利亚最大的金矿之一的运营周五不得不暂时停课，因为其中一个地方的墙壁部分倒塌我的水坝。"},{"s":50.84,"e":59.68,"en":"The wall collapse at the Cadia Mine came just a few days after two earthquakes hit the area.","zh":"卡迪亚矿井墙壁倒塌就在两次地震发生几天后該區域。"},{"s":59.68,"e":70.84,"en":"The damage to the dam wall was noticed in the late afternoon on Friday when workers found a section of the northern dam wall had collapsed into the southern dam.","zh":"大坝墙体受损情况引人注目周五下午晚些时候，工人们发现了北坝墙的一部分已经坍塌至南侧大坝。"},{"s":70.84,"e":78.62,"en":"The dams contain waste products of mining and can contain materials which are harmful to the environment and human health.","zh":"水坝中含有采矿产生的废料和可能含有对人体有害的物质环境和人类健康。"},{"s":78.62,"e":86.64,"en":"The dams are generally constructed using earth fill and are gradually raised over time.","zh":"水坝一般采用土石方建造并随着时间的推移逐渐升高。"},{"s":86.64,"e":97.84,"en":"The company was unable to confirm whether the recent earthquakes had contributed to the dam's wall collapse but said it was conducting a thorough investigation.","zh":"该公司无法确认最近的地震对大坝的墙体造成了影响但表示正在进行彻底的调查。"},{"s":97.84,"e":110.6,"en":"A company spokesperson said that operations at the site had been halted while the investigation is ongoing and that the break had posed no safety threat to workers.","zh":"该公司发言人表示，该网站已暂停调查正在进行，而且这次中断并没有造成对工人的安全威胁。"},{"s":110.6,"e":115.3,"en":"Questions 1 and 2 are based on the news report you have just heard.","zh":"问题1和问题2基于您刚刚听到的新闻报道。"},{"s":115.3,"e":116.9,"en":"Question 1.","zh":"问题1."},{"s":116.9,"e":135.86,"en":"What happened at one of Australia's largest gold mines?","zh":"澳大利亚最大的金矿之一发生了什么地雷？"},{"s":135.86,"e":137.54,"en":"Question 2.","zh":"问题2."},{"s":137.54,"e":155.86,"en":"What did the spokesperson say about the incident?","zh":"发言人对此事有何评论？"},{"s":155.86,"e":158.06,"en":"News Report 2.","zh":"新闻报道2."},{"s":158.06,"e":166.96,"en":"Two boys and four girls were born on Monday to the surprise of a young couple and doctors who had expected five babies.","zh":"两名男孩和四名女孩出生周一，一对年轻夫妇大吃一惊以及预期有五个孩子的医生。"},{"s":166.96,"e":173.24,"en":"This was the first record of six babies being born at the same time in that region.","zh":"这是第一个六胎婴儿的记录同时出生在那个地区。"},{"s":173.24,"e":179.72,"en":"The doctors prepared from early in the morning to help deliver five tiny citizens.","zh":"医生们从一大早就开始准备帮助接生五位小公民。"},{"s":179.72,"e":184.7,"en":"They were in the operating room with five teams of doctors, one for each baby.","zh":"他们在手术室里，有五个人一组医生，负责每个婴儿。"},{"s":184.7,"e":192.3,"en":"The first five babies were delivered successfully and all baby beds were occupied.","zh":"前五名婴儿均顺利出生，所有婴儿床都被占了。"},{"s":192.3,"e":198.4,"en":"And then, all of a sudden, it turned out there was another waiting to come out.","zh":"然后，突然间，一切都变了外面还有另外一个人在等着出来。"},{"s":198.4,"e":204.52,"en":"The doctors said the babies were in healthy condition but could not go home immediately.","zh":"医生说，婴儿身体健康但不能立即回家。"},{"s":204.52,"e":210.4,"en":"They needed to stay in the hospital for two to three months for medical supervision.","zh":"他们需要住院进行两到三个月的医疗监督。"},{"s":210.4,"e":219.5,"en":"The mother, who was in stable condition, could return home a day later if all physical tests came back normal.","zh":"母亲目前情况稳定，如果身体一切正常，请晚一天回家测试结果恢复正常。"},{"s":219.5,"e":229.6,"en":"The baby's mother commented that they had already prepared room for five babies at home, so they will have to rearrange things for their happy surprise.","zh":"婴儿的母亲表示，他们已经在家里为五个婴儿准备了房间，所以他们将不得不重新安排他们的惊喜。"},{"s":229.6,"e":237.06,"en":"The new parents have yet to name the sixth baby but are considering either Lily or Rose.","zh":"新父母尚未命名第六个孩子，但正在考虑莉莉或玫瑰。"},{"s":237.06,"e":282.48,"en":"Questions three and four are based on the news report you have just heard.","zh":"问题三和问题四基于您刚刚听到的新闻报道。"},{"s":282.48,"e":290.46,"en":"A Spanish island called Palmador has been bought by a family from Europe for 18 million euros.","zh":"西班牙帕尔马多尔岛已被购买来自欧洲的一个家庭以1800万美元的价格欧元。"},{"s":290.46,"e":295.68,"en":"The island is often described as heaven on earth by holiday makers.","zh":"该岛经常被描述为度假者的地球。"},{"s":295.68,"e":303.2,"en":"For decades, tourists have been flocking to Palmador, which is located off the southeast coast of Spain.","zh":"几十年来，游客们纷纷涌向帕尔马多，位于西班牙。"},{"s":303.2,"e":308.82,"en":"They come to enjoy its unspoiled beaches and crystal clear waters.","zh":"他们来这里享受未受污染的海滩和清澈的海水。"},{"s":308.82,"e":313.7,"en":"Its natural beauty is protected as it lies inside a natural park.","zh":"它的自然美景受到保护在自然公园内。"},{"s":313.7,"e":324.28,"en":"Although Palmador is one of the most famous private islands in the world, its seafront is public land and is a favorite destination for famous people.","zh":"尽管Palmador是最著名的世界上的私人岛屿，其海滨是公共土地，是名人。"},{"s":324.28,"e":332.46,"en":"When the island was put up for sale, it was offered to the local government but proved too expensive for the local authorities.","zh":"当这座岛被挂牌出售时，它被提供给当地政府，但这对当地政府来说成本太高。"},{"s":332.46,"e":344.14,"en":"It is unclear whether the new owners have the power to ban tourists from the island, but with their newfound luxury comes the responsibility for its protection and maintenance.","zh":"目前尚不清楚新东家是否禁止游客进入该岛的权力，但随着他们新获得的奢华而来的是责任以便对其进行保护和维护。"},{"s":344.14,"e":349.36,"en":"The island is less than two miles long and half a mile wide.","zh":"该岛长度不到两英里宽半英里。"},{"s":349.36,"e":358.32,"en":"It is said to have a remarkable location that few other private islands of this size can match, according to estate agents.","zh":"据说它有一个非凡的地理位置很少有其他私人岛屿能达到这种规模据房地产经纪人称，可以匹配。"},{"s":358.32,"e":370.08,"en":"Palmador is the perfect place to retreat to, somewhere to get away from the city noise and relax in beautiful surroundings with zero stress.","zh":"Palmador是完美的休憩之地，远离城市喧嚣的地方并在毫无压力的美丽环境中放松身心。"},{"s":370.08,"e":375.76,"en":"Questions 5 to 7 are based on the news report you have just heard.","zh":"问题5至7基于您刚刚听到的新闻报道。"},{"s":375.76,"e":377.4,"en":"Question 5.","zh":"问题5."},{"s":377.4,"e":396.86,"en":"What do we learn from the news report about the Spanish island Palmador?","zh":"我们从新闻报道中了解到了什么关于西班牙帕尔马多尔岛？"},{"s":396.86,"e":399.1,"en":"Question 6.","zh":"问题6."},{"s":399.1,"e":417.74,"en":"What do holidaymakers come to Palmador to enjoy?","zh":"度假者来到Palmador享受什么？"},{"s":417.74,"e":419.52,"en":"Question 7.","zh":"问题7."},{"s":419.52,"e":438.08,"en":"What do estate agents say about Palmador?","zh":"房地产经纪人对Palmador有何评价？"},{"s":438.08,"e":439.44,"en":"Section B.","zh":"B部分。"},{"s":439.44,"e":444.2,"en":"Directions In this section, you will hear two long conversations.","zh":"说明在这一部分中，你将听到两个长时间的谈话。"},{"s":444.2,"e":448.22,"en":"At the end of each conversation, you will hear four questions.","zh":"每次对话结束时，你将听四个问题。"},{"s":448.22,"e":452.52,"en":"Both the conversation and the questions will be spoken only once.","zh":"对话和问题都将只讲过一次。"},{"s":452.52,"e":460.12,"en":"After you hear a question, you must choose the best answer from the four choices marked A, B, C, and D.","zh":"听完问题后你必须选择标记的四个选项中的最佳答案A、B、C和D。"},{"s":460.12,"e":467.38,"en":"Then, mark the corresponding letter on answer sheet 1 with a single line through the center.","zh":"然后在答题纸上标记相应的字母1一条线穿过中心。"},{"s":467.38,"e":468.8,"en":"Conversation 1.","zh":"对话1。"},{"s":468.8,"e":469.54,"en":"Hi.","zh":"你好。"},{"s":469.54,"e":470.82,"en":"Christie's Gym Center.","zh":"克里斯蒂健身中心。"},{"s":470.82,"e":472.32,"en":"How can I help you?","zh":"我怎么帮你？"},{"s":472.32,"e":472.98,"en":"Hi.","zh":"你好。"},{"s":472.98,"e":476.66,"en":"I'm calling to ask about the newly scheduled gym classes.","zh":"我打电话来询问新安排的体育课。"},{"s":476.66,"e":479.38,"en":"I'm just wondering if I can get a discount on them.","zh":"我只是想知道我是否可以得到一个折扣。"},{"s":479.38,"e":481.22,"en":"Are you already a member?","zh":"您已经是会员了吗？"},{"s":481.22,"e":481.9,"en":"Yes.","zh":"是的。"},{"s":481.9,"e":486.66,"en":"I signed up two months ago, but I haven't been to any of the group classes yet.","zh":"我两个月前就报名了，但是没有参加过任何小组课程然而。"},{"s":486.66,"e":488.36,"en":"Can I take your name, please?","zh":"可以给我你的名字吗？"},{"s":488.36,"e":488.9,"en":"Yes.","zh":"是的。"},{"s":488.9,"e":491.2,"en":"My name is Carol Friedman.","zh":"我叫卡罗尔弗里德曼。"},{"s":491.2,"e":492.48,"en":"Carol Friedman.","zh":"卡罗尔·弗里德曼。"},{"s":492.48,"e":493.3,"en":"That's right.","zh":"这是正确的。"},{"s":493.3,"e":494.88,"en":"And you signed up two months ago.","zh":"您两个月前就报名了。"},{"s":494.88,"e":504.68,"en":"Currently, we are offering existing members discounts off two of our brand new classes, Hot Yoga and Advanced Spinning.","zh":"目前，我们为现有会员提供折扣我们的两个全新课程，热瑜伽和高级纺纱。"},{"s":504.68,"e":509.3,"en":"But the discount doesn't apply to any of our regular classes, I'm afraid.","zh":"但折扣不适用于任何恐怕我们的常规课程。"},{"s":509.3,"e":512.08,"en":"I'm only interested in the new classes.","zh":"我只对新课程感兴趣。"},{"s":512.08,"e":516.83,"en":"So, how much of a discount is there on these two new classes?","zh":"那么，折扣有多少呢关于这两个新课程？"},{"s":516.83,"e":525.82,"en":"The same discount of 20% is being offered to everyone at the door on a first-come, first-served basis for the first month.","zh":"同样20%的折扣为在门口的每个人提供先到先得月。"},{"s":525.82,"e":528.58,"en":"It's a shame you missed out on the general discount.","zh":"很遗憾你错过了普惠折扣。"},{"s":528.58,"e":529.64,"en":"I see.","zh":"我懂了。"},{"s":529.64,"e":534.56,"en":"But you can get 25% off if you sign up in advance.","zh":"但如果你提前报名。"},{"s":534.56,"e":537.08,"en":"Which of the two classes are you thinking about?","zh":"你想的是这两门课中的哪一门关于？"},{"s":537.08,"e":541.28,"en":"Well, I guess I am only really interested in Hot Yoga.","zh":"嗯，我想我只是真的感兴趣在热瑜伽中。"},{"s":541.28,"e":545.22,"en":"Can you sign me up for the 10-week course on Thursday evenings?","zh":"你能帮我报名参加10周四晚上有为期一周的课程吗？"},{"s":545.22,"e":546.16,"en":"Sure.","zh":"当然。"},{"s":546.16,"e":548.3,"en":"Would you prefer to pay in advance?","zh":"您希望提前付款吗？"},{"s":548.3,"e":552.44,"en":"No, I don't like giving my card details over the phone anyway.","zh":"不，我不喜欢提供我的银行卡信息无论如何，通过电话。"},{"s":552.44,"e":553.54,"en":"Okay then.","zh":"好的。"},{"s":553.54,"e":558.64,"en":"As you are already a member, the fee for the class will just be added to your monthly bill.","zh":"由于您已经是会员，因为该类将被添加到您的每月账单。"},{"s":558.64,"e":559.76,"en":"That's perfect.","zh":"那很完美。"},{"s":559.76,"e":560.94,"en":"Thanks for your help.","zh":"感谢您的帮助。"},{"s":560.94,"e":563.38,"en":"See you Thursday.","zh":"星期四见。"},{"s":563.38,"e":568.16,"en":"Questions 8 to 11 are based on the conversation you have just heard.","zh":"问题8至11基于您刚才听到的对话。"},{"s":568.16,"e":569.74,"en":"Question 8.","zh":"问题8."},{"s":569.74,"e":572.52,"en":"What do we learn about the woman from the conversation?","zh":"我们从这个女人身上学到了什么对话？"},{"s":572.52,"e":589.8,"en":"Question 9.","zh":"问题9."},{"s":589.8,"e":607.66,"en":"What is the gym center doing right now?","zh":"健身中心现在在做什么？"},{"s":607.66,"e":609.32,"en":"Question 10.","zh":"问题10."},{"s":609.32,"e":627.48,"en":"What does the man say is a pity for the woman?","zh":"男人说了可惜对于女人来说？"},{"s":627.48,"e":629.26,"en":"Question 11.","zh":"问题11."},{"s":629.26,"e":647.87,"en":"Why is the woman unwilling to pay in advance?","zh":"为什么女人不愿意付钱进步？"},{"s":647.87,"e":649.31,"en":"Conversation 2.","zh":"对话2。"},{"s":649.31,"e":653.25,"en":"Well, I think that was quite a successful trip in the end.","zh":"嗯，我认为那是一个相当成功的最终的旅行。"},{"s":653.25,"e":654.57,"en":"Don't you think, Jenny?","zh":"你不这么认为吗，珍妮？"},{"s":654.57,"e":655.79,"en":"Absolutely.","zh":"绝对地。"},{"s":655.79,"e":658.87,"en":"There are lots of great potential markets here in China.","zh":"这里有很多巨大的潜在市场在中国。"},{"s":658.87,"e":665.77,"en":"So, I'm sure that the head office in London will be pleased once we get back and present our research.","zh":"所以，我确信总部一旦我们回来，伦敦会很高兴并展示我们的研究成果。"},{"s":665.77,"e":666.63,"en":"Okay.","zh":"好的。"},{"s":666.63,"e":668.87,"en":"We've got a bit of spare time now.","zh":"我们现在有一些空闲时间。"},{"s":668.87,"e":671.61,"en":"Can we discuss the return trip to the head office?","zh":"我们可以讨论一下返回总公司？"},{"s":671.61,"e":672.53,"en":"Sure.","zh":"当然。"},{"s":672.53,"e":678.85,"en":"I've checked the availability of flights from Beijing to London on the 22nd, and you have a choice.","zh":"我查了一下从北京出发的航班22号去伦敦，你有一个选择。"},{"s":678.85,"e":690.63,"en":"There's a flight arriving the following morning with a two-hour stopover in Dubai, or a flight arriving at 11.30 in the evening with a five-hour stopover in Amsterdam.","zh":"第二天早上有一班航班抵达在迪拜停留两小时，或者航班于晚上11:30抵达在阿姆斯特丹停留五个小时。"},{"s":690.63,"e":691.33,"en":"Right.","zh":"正确的。"},{"s":691.33,"e":694.07,"en":"Well, that's obvious then, isn't it?","zh":"那么，这很明显，不是吗？"},{"s":694.07,"e":696.13,"en":"Okay, so that's Dubai.","zh":"好的，这就是迪拜。"},{"s":696.13,"e":699.53,"en":"I've booked a room in a hotel about a mile from the office.","zh":"我在酒店预订了房间距办公室一英里。"},{"s":699.53,"e":703.23,"en":"The nearest metro station is Earls Court.","zh":"最近的地铁站是EarlsCourt。"},{"s":703.23,"e":704.35,"en":"Great.","zh":"伟大的。"},{"s":704.35,"e":709.23,"en":"Can you find a map that shows where the hotel is and send it to me online?","zh":"你能找到一张显示哪里的地图吗酒店是，然后发给我在线的？"},{"s":709.23,"e":712.05,"en":"I've never been to the head office, you know.","zh":"我从来没有去过总部，你知道。"},{"s":712.05,"e":718.05,"en":"I want to see if I can get one of those rental bicycles and ride to the office, just for fun.","zh":"我想看看我能否得到租一辆自行车，骑到办公室，只是为了好玩。"},{"s":718.05,"e":723.45,"en":"For the presentation, I'll bring my own laptop and hook it up to their projector.","zh":"为了演讲，我会带上自己的笔记本电脑并将其连接到投影仪上。"},{"s":723.45,"e":726.31,"en":"Do you remember the capacity of their meeting room?","zh":"你还记得他们会议的容量吗房间？"},{"s":726.31,"e":728.19,"en":"No, but I'll check.","zh":"没有，但我会检查一下。"},{"s":728.19,"e":729.83,"en":"Just one more thing.","zh":"还有一件事。"},{"s":729.83,"e":732.99,"en":"I'll pay everything with my own card, right?","zh":"我会用自己的卡支付所有费用，对吗？"},{"s":732.99,"e":735.25,"en":"And I'll submit my claims form afterwards?","zh":"然后我再提交索赔表吗？"},{"s":735.25,"e":736.85,"en":"No problem.","zh":"没问题。"},{"s":736.85,"e":739.25,"en":"Just remember to keep all your receipts.","zh":"只要记住保留所有收据即可。"},{"s":739.25,"e":741.91,"en":"You remember the trouble you had last time.","zh":"你还记得上次遇到的麻烦。"},{"s":741.91,"e":745.23,"en":"Oh, don't remind me.","zh":"哦，别提醒我。"},{"s":745.23,"e":810.5,"en":"Questions 12 to 15 are based on the conversation you have just heard.","zh":"问题12至15基于您刚才听到的对话。"},{"s":810.5,"e":812.28,"en":"Question 15.","zh":"问题15."},{"s":812.28,"e":853.74,"en":"What did the woman remind the man to do at the end of the conversation?","zh":"女人提醒男人什么对话结束时该做什么？"},{"s":853.74,"e":883.74,"en":"Then mark the corresponding letter on Answer Sheet 1 with the single line through the center.","zh":"然后在答题纸上标记相应的字母1，单线通过中心。"},{"s":883.74,"e":895.04,"en":"The researchers analyzed databases which held information from 162 countries for the period 2004 to 2010.","zh":"研究人员分析了包含以下信息的数据库：2004年至2010年期间涉及162个国家。"},{"s":895.04,"e":901.56,"en":"Countries were classified according to the respect they gave to women's economic and social rights.","zh":"各国根据其所尊重的赋予妇女经济和社会权利。"},{"s":901.56,"e":903.84,"en":"There were three categories.","zh":"有三个类别。"},{"s":903.84,"e":907.18,"en":"They were high, moderate, and poor.","zh":"他们分为高等、中等和贫困三种类型。"},{"s":907.18,"e":916.52,"en":"Analysis of the data showed that countries with strong women's rights had better health than those where women's rights were not as respected.","zh":"数据分析显示，拥有强大权利的妇女比那些妇女权利不受尊重。"},{"s":916.52,"e":926.1,"en":"The health indicators studied included disease prevention, reproductive health, death rates, and life expectancy.","zh":"研究的健康指标包括疾病预防、生殖健康、死亡率和预期寿命。"},{"s":926.1,"e":940.14,"en":"Furthermore, in countries where women's rights were most respected but where access to hospitals and doctors was below average, health outcomes were still better than in countries rated as moderate or poor.","zh":"此外，在妇女权利最不发达的国家尊重，但获得医院和医生低于平均水平，但健康结果仍然较好高于被评为中等或较差的国家。"},{"s":940.14,"e":949.06,"en":"This confirms that, even with a lack of resources, if a country has strong women's rights, the health outcomes are better.","zh":"这证实了，即使缺乏如果一个国家有强大的妇女权利，健康结果更佳。"},{"s":949.06,"e":954.46,"en":"Thus, the researchers argue that gender equality is not just a women's rights issue.","zh":"因此，研究人员认为，性别平等不仅仅是妇女权利问题。"},{"s":954.46,"e":957.28,"en":"It is also a development issue.","zh":"这也是一个发展问题。"},{"s":957.28,"e":960.87,"en":"This is because better health aids economic development.","zh":"这是因为更好的健康有助于经济发展。"},{"s":960.87,"e":967.28,"en":"They note that the value of women's rights has often been questioned from an economic standpoint.","zh":"他们指出，妇女权利的价值经常从经济角度受到质疑。"},{"s":967.28,"e":974.5,"en":"Some have argued that ensuring those rights would limit progress, but this study indicates the opposite.","zh":"一些人认为，确保这些权利将限制进展，但这项研究表明相反的情况。"},{"s":974.5,"e":979.44,"en":"Questions 16 to 18 are based on the passage you have just heard.","zh":"问题16至18基于您刚刚听到的段落。"},{"s":979.44,"e":981.4,"en":"Question 16.","zh":"问题16."},{"s":981.4,"e":999.41,"en":"What did the researchers of the new study try to determine?","zh":"新研究的研究人员尝试确定？"},{"s":999.41,"e":1002.17,"en":"Question 17.","zh":"问题17."},{"s":1002.17,"e":1021.83,"en":"What does the passage say about countries lacking in medical resources?","zh":"这篇文章对缺乏医疗资源方面？"},{"s":1021.83,"e":1023.67,"en":"Question 18.","zh":"问题18."},{"s":1023.67,"e":1042.1,"en":"What has often been questioned regarding women's rights?","zh":"关于妇女权利，人们常常质疑什么？"},{"s":1042.1,"e":1043.94,"en":"Passage 2.","zh":"段落2。"},{"s":1043.94,"e":1054.45,"en":"Sunshine and high temperatures can mean picnics in parks and trips to beaches, but they can make your body react in some strange ways.","zh":"阳光和高温意味着可以在公园和海滩之旅，但他们可以让你的身体做出一些奇怪的反应。"},{"s":1054.45,"e":1058.9,"en":"First, sunshine can actually affect your breath.","zh":"首先，阳光实际上会影响你的呼吸。"},{"s":1058.9,"e":1074.62,"en":"You may think that summer is the perfect time to go on a date or chat with an attractive boy or girl, but excessive heat can cause you to lose water, which has been proven to have a pretty unattractive side effect, bad breath.","zh":"你可能认为夏天是完美的约会或聊天的时间和一个有吸引力的男孩或女孩，但过度高温会导致你失水，已被证明具有相当不吸引人的副作用，口臭。"},{"s":1074.62,"e":1078.74,"en":"When you are lacking water, your mouth becomes dry.","zh":"当你缺水时，你的嘴巴就会干燥。"},{"s":1078.74,"e":1084.44,"en":"Bacteria accumulates because there isn't enough water in your mouth to wash it away.","zh":"细菌积聚是因为体内水分不足用嘴巴漱口。"},{"s":1084.44,"e":1088.22,"en":"Sunshine can stop you from sweating too.","zh":"阳光也可以阻止你出汗。"},{"s":1088.22,"e":1100.46,"en":"The body's normal temperature is 36 to 37 degrees centigrade, but if it heats up to 40 to 41 degrees, you may find yourself getting heat stroke.","zh":"人体的正常体温是36至37摄氏度，但如果温度升至40到41度，你可能会发现自己中暑。"},{"s":1100.46,"e":1112.4,"en":"At that point, your heat regulatory system can essentially quit, which stops you from sweating, as your body tries to keep water around your vital organs.","zh":"此时，你的体温调节系统可以本质上就是戒烟，这样你就不会出汗了，因为你的身体会努力保持周围的水分重要器官。"},{"s":1112.4,"e":1118.52,"en":"However, the sun can have a positive influence on your body by raising your energy levels.","zh":"然而，阳光可以产生积极的影响通过提高你的能量水平来对你的身体产生影响。"},{"s":1118.52,"e":1124.52,"en":"You might feel like the sun is giving you extra energy for your day, which is actually happening.","zh":"你可能会觉得太阳正在给予为你的每一天补充能量，确实正在发生。"},{"s":1124.52,"e":1132.62,"en":"And vitamin D from sunshine can help your body to absorb certain minerals which are linked to building stronger bones.","zh":"阳光中的维生素D可以帮助你身体吸收某些矿物质，这些矿物质与从而强健骨骼。"},{"s":1132.62,"e":1143.58,"en":"Therefore, I suggest you spend more time in the park with your friends, but make sure you apply lots of skin protection and fill up those water bottles too.","zh":"因此，我建议你多花点时间和朋友一起去公园，但一定要你涂了很多皮肤保护剂并填充还有那些水瓶。"},{"s":1143.58,"e":1148.16,"en":"Questions 19 to 21 are based on the passage you have just heard.","zh":"问题19至21基于您刚刚听到的段落。"},{"s":1148.16,"e":1150.98,"en":"Question 19.","zh":"问题19."},{"s":1150.98,"e":1169.46,"en":"What does the passage say about hot sunshine?","zh":"文章中关于炎热的阳光是怎么说的？"},{"s":1169.46,"e":1171.08,"en":"Question 20.","zh":"问题20."},{"s":1171.08,"e":1190.45,"en":"What does the passage say is a negative side effect of water loss?","zh":"文章中说的否定词是什么失水的副作用？"},{"s":1190.45,"e":1192.21,"en":"Question 21.","zh":"问题21."},{"s":1192.21,"e":1210.61,"en":"What is said to be a positive effect of sunshine?","zh":"据称这是一种积极影响阳光？"},{"s":1210.61,"e":1212.91,"en":"Passage 3.","zh":"段落3。"},{"s":1212.91,"e":1219.03,"en":"Left-handed people can find it inconvenient to do certain things, writing in a notebook, for example.","zh":"左撇子可能会觉得不方便做某些事情，写在笔记本上，例子。"},{"s":1219.03,"e":1223.79,"en":"But there are a number of advantages of being left-handed.","zh":"但有很多优点左撇子。"},{"s":1223.79,"e":1229.95,"en":"Research found that they were over-represented among fighters in combat sports.","zh":"研究发现，他们在格斗运动中的战士。"},{"s":1229.95,"e":1233.89,"en":"Left-handed fighters also had higher chances to win.","zh":"左撇子战士也有更高的机会赢。"},{"s":1233.89,"e":1237.03,"en":"This confirms the fighter theory.","zh":"这证实了战斗机理论。"},{"s":1237.03,"e":1240.93,"en":"Left-handers may also be better at remembering events.","zh":"左撇子可能记忆力更好事件。"},{"s":1240.93,"e":1247.15,"en":"The explanation is that the two brain spheres of left-handers are more strongly connected.","zh":"解释是，两个大脑球体左撇子之间的联系更为紧密。"},{"s":1247.15,"e":1252.01,"en":"Being left-handed might be a factor in mathematical ability.","zh":"左撇子可能是数学能力。"},{"s":1252.01,"e":1259.35,"en":"An Italian study found that for simple arithmetic, there was little difference between right and left-handed performance.","zh":"意大利的一项研究发现，对于简单的算术来说，左右之间几乎没有区别手表演。"},{"s":1259.35,"e":1264.33,"en":"But for more difficult problem solving, left-handers won out.","zh":"但对于更困难的问题解决，左撇子获胜了。"},{"s":1264.33,"e":1267.49,"en":"No one understands the reason for this.","zh":"没有人明白其中的原因。"},{"s":1267.49,"e":1270.28,"en":"Left-handed people may think differently.","zh":"左撇子的想法可能有所不同。"},{"s":1270.28,"e":1279.47,"en":"In one study, researchers showed the participants columns of abstract illustrations and asked them which ones they would prefer.","zh":"在一项研究中，研究人员向参与者展示了抽象插图，并问他们哪些他们更喜欢。"},{"s":1279.47,"e":1284.09,"en":"Left-handed people were more likely to prefer the images on the left.","zh":"左撇子更有可能喜欢左边的图像。"},{"s":1284.09,"e":1287.77,"en":"Right-handed people preferred the ones on the right.","zh":"惯用右手的人更喜欢正确的。"},{"s":1287.77,"e":1292.13,"en":"Both groups disliked stuff on their opposite side.","zh":"两个群体都不喜欢对方的东西。"},{"s":1292.13,"e":1297.23,"en":"Left-handers are also over-represented in professional, interactive sports.","zh":"左撇子在职业中也占了很大比例，互动体育。"},{"s":1297.23,"e":1303.41,"en":"Researchers have looked at the influence of being left-handed on performance in interactive sports.","zh":"研究人员研究了左撇子在互动运动中的表现。"},{"s":1303.41,"e":1308.99,"en":"Those that require the fastest reaction give left-handers the biggest advantage.","zh":"那些需要最快反应的人会选择左边手最大的优势。"},{"s":1308.99,"e":1316.29,"en":"So, if you have a left-handed child, you should encourage them to play table tennis, baseball, and tennis.","zh":"所以如果你有一个左撇子孩子，你应该鼓励他们打乒乓球，棒球和网球。"},{"s":1316.29,"e":1321.41,"en":"Being left-handed maximizes their chances of success in these sports.","zh":"左撇子可以最大程度地提高成功的机会在这些运动中。"},{"s":1321.41,"e":1326.77,"en":"Questions 22 to 25 are based on the passage you have just heard.","zh":"问题22至25基于您刚刚听到的段落。"},{"s":1326.77,"e":1328.55,"en":"Question 22.","zh":"问题22."},{"s":1328.55,"e":1346.42,"en":"What does the passage say about left-handed people?","zh":"这篇文章对左撇子有何看法人们？"},{"s":1346.42,"e":1348.4,"en":"Question 23.","zh":"问题23."},{"s":1348.4,"e":1366.58,"en":"What is said to be special about left-handed people?","zh":"左边有什么特别之处手的人？"},{"s":1366.58,"e":1368.78,"en":"Question 24.","zh":"问题24."},{"s":1368.78,"e":1388.12,"en":"Why are left-handed people better at solving more difficult problems?","zh":"为什么左撇子更善于解决问题更困难的问题？"},{"s":1388.12,"e":1390.26,"en":"Question 25.","zh":"问题25."},{"s":1390.26,"e":1408.5,"en":"What should parents do about a left-handed child?","zh":"父母应该为左撇子做些什么孩子？"},{"s":1408.5,"e":1411.45,"en":"That's the end of Listening Comprehension.","zh":"听力理解到此结束。"}]}];
